package modules

// varDescriptions: what every /bs variable does (like the Python bot).
var varDescriptions = map[string]string{
	"MIRROR_LOG_ID":                "Chat ID where the finish message of /mirror tasks is also sent, with its buttons. Int. Add -100 before the id.",
	"LINKS_LOG_ID":                 "Chat ID where every task's link/source is logged when it starts (Task Started + Source). Int. Add -100 before the id.",
	"GDRIVE_WORKER":                "Worker that downloads PUBLIC Google Drive files and folders when there is no token.pickle (or the token can't open the link). Empty = off.",
	"MEDIA_STORE":                  "Default for Media Store: every leeched file gets a Store Link, anyone who opens it gets the file from the bot in PM. Users can change it for themselves in User Settings → Leech. Bool",
	"INCOMPLETE_TASK_NOTIFIER":     "Get incomplete task messages after restart: the tasks that were running are listed (with links to their commands in groups) in the chats they were started in. Needs DATABASE_URL. Default is False. Bool",
	"DISABLE_VT":                   "Disable Video Tools (-vt) for all users. Default is False. Bool",
	"VT_CUSTOM_CMDS":               "Extra tools for the Video Tools menu (-vt), one per line as <code>name: ffmpeg args</code> (the args come after <code>-i video</code>), e.g. <code>No Audio: -map 0 -map -0:a -c copy</code>. Str",
	"DISABLE_FF_MODE":              "Disable FFmpeg Cmds (-ff) for all users. When True the option is hidden from User Settings. Default is False. Bool",
	"REAL_DEBRID_API":              "real-debrid.com API token: the same for the hosters Real-Debrid supports (used when DEBRID_LINK_API is not set or fails). Str",
	"DEBRID_LINK_API":              "debrid-link.com API key: links of 360+ hosters (Mega, 1fichier, Rapidgator, Uptobox ...) are downloaded through debrid-link, fast and without the host's limits. Str",
	"SAFE_MODE":                    "Hide the file names and the source link in the leech log and the finish message (only the file links stay). Default is False. Bool",
	"AUTO_DELETE_MESSAGE_DURATION": "Seconds after which the bot deletes its short messages (usage, errors like limits or access) together with the command. 0 = keep them. Int",
	"PM_ACCESS":                    "Let everyone use the bot in private chat, like in authorized groups. Blacklisted users stay blocked. Default is False. Bool",
	"SET_COMMANDS":                 "Register the bot commands in Telegram's command menu at start. Default is True. Bool",
	"WEB_PINCODE":                  "Ask for the pincode on the file selection web page. False = the Select Files link opens the list directly. Default is True. Bool",
	"YT_DLP_OPTIONS":               "Default yt-dlp options for everyone (command line style, e.g. --embed-subs --sub-langs en). Users can add their own in /us → Universal → YT-DLP Options. Str",
	"PLAYLIST_LIMIT":               "Maximum number of videos taken from a yt-dlp playlist (0 = no limit). Int",
	"LEECH_FILENAME_REMNAME":       "Remove words from every leeched file name. Separate them by | (e.g. www.site.com|[Group]). Str",
	"EXTENSION_FILTER":             "File extensions that won't be uploaded, for all users (e.g. .txt .nfo .url). Separate them by space. Users can add their own in /us. Str",
	"EXCEP_CHATS":                  "Chats (IDs separated by space) that don't use logging: no Leech Started and no copy in LEECH_LOG_ID for tasks started there. Str",
	"DELETE_LINKS":                 "Delete TgLink/Magnet/File on Start of Task to Auto Clean Group. Default is False. Bool",
	"RICH_MESSAGES":                "Send the status as a Telegram Rich Message: a Cancel button inside every task and lines between tasks, instead of /cancel commands. Default is False. Bool",
	"CLEAN_LOG_MSG":                "Delete the \"Leech Started\" message in LEECH_LOG_ID after the upload is done. Default is False. Bool",
	"USER_TIME_INTERVAL":           "Seconds a user must wait between two tasks (0 = no wait). Owner and sudo are not limited. Int",
	"SAVE_MSG":                     "Adds a 📨 Save Message button to leeched files and the finish message: whoever presses it gets a copy in his PM (good for groups and the log channel). Bool",
	"SOURCE_LINK":                  "Adds a Source Link button to the finish message with the original link (or the Telegram message of the file). Bool",
	"FSUB_IDS":                     "Force subscribe: channel IDs (-100...) separated by space. In groups users must join them before starting a task, they get Join buttons. The bot must be admin in those channels. Owner and sudo are not checked. Str",
	"DISABLE_TORRENTS":             "Block torrents: magnet links, .torrent links and .torrent files are refused, and aria2 does not follow a link that turns out to be a torrent. Everything else keeps working. Always on when the bot runs on Heroku (Heroku does not allow torrents). Default is True. Bool",
	"TORRENT_TIMEOUT":              "Dead torrent timeout in seconds: a torrent or magnet that downloads nothing for this long is cancelled (Dead Torrent!). 0 = never. Default is 600. Int",
	"USER_SESSION_STRING":          "Pyrogram/Telethon style session string of a Telegram account (premium recommended). Used to download/upload faster and to upload files up to 4GB. Generate it with /bs → User Session or a session generator.",
	"LEECH_LOG_ID":                 "Chat ID to where leeched files would be uploaded (the bot copies them to the user from there). Int. NOTE: Only available for superGroup/channel. Add -100 before channel/superGroup id. In short don't add bot id or your id! The old DUMP_CHAT_ID is the same channel now.",
	"STATUS_UPDATE_INTERVAL":       "Time in seconds after which the progress/status message will be updated. Recommended 10 seconds at least.",
	"STATUS_LIMIT":                 "Limit the no. of tasks shown in status message with buttons. Default is 10. NOTE: Recommended limit is 4 tasks.",
	"LEECH_SPLIT_SIZE":             "Size of split in bytes. Default is 2GB. Default is 4GB if your account is premium.",
	"AS_DOCUMENT":                  "Default type of Telegram file upload. Default is False mean as media.",
	"AUTO_THUMBNAIL":               "Use a movie/series poster from TMDB as the thumbnail of every leeched file (needs TMDB_ACCESS_TOKEN). Users can also enable it in /us. Bool",
	"EQUAL_SPLITS":                 "Split files larger than LEECH_SPLIT_SIZE into equal parts size (Not working with zip cmd). Default is False.",
	"MEDIA_GROUP":                  "View Uploaded splitted file parts in media group. Default is False.",
	"LEECH_FILENAME_PREFIX":        "Add custom word prefix to leeched file name. Str",
	"LEECH_FILENAME_SUFFIX":        "Add custom word suffix to leeched file name. Str",
	"LEECH_FILENAME_CAPTION":       "Add custom word caption to leeched file/vedios. Str",
	"BASE_URL":                     "Valid BASE URL where the bot is deployed to use torrent web files selection. Format of URL should be http://myip, where myip is the IP/Domain(public) of your bot or if you have chosen port other than 80 so write it in this format http://myip:port (http and not https). Str",
	"BOT_MAX_TASKS":                "Maximum number of Task Bot will Run parallel. (Queue Tasks Included). Int",
	"USER_MAX_TASKS":               "Limit the Maximum task for users of group at a time. use the Int",
	"LEECH_LIMIT":                  "To limit the Torrent/Direct/ytdlp leech size. the default unit is GB. Int",
	"TORRENT_LIMIT":                "To limit the size of torrent download. the default unit is GB. Int",
	"DIRECT_LIMIT":                 "To limit the size of direct link download. the default unit is GB. Int",
	"YTDLP_LIMIT":                  "To limit the size of ytdlp download. the default unit is GB. Int",
	"MEGA_LIMIT":                   "To limit the size of Mega download. the default unit is GB. Int",
	"DAILY_LEECH_LIMIT":            "Total size upto which user can Leech in one day. the default unit is GB. Int",
	"DAILY_TASK_LIMIT":             "Maximum task a user can do in one day. use the Int",
	"SHORTENER":                    "Shortener site domain for token links (e.g. gplinks.com). Str",
	"SHORTENER_API":                "API key of the SHORTENER site. Str",
	"SHORTENER_ENABLED":            "Enable the shortener token system for users. Bool",
	"TOKEN_TIMEOUT":                "Token timeout for each group member in sec. Int",
	"UPSTREAM_REPO":                "Your github repository link, used by /restart to update the code. If your repo is private use https://username:{githubtoken}@github.com/{username}/{reponame} format. Default is Tj-Bots/azml-go.",
	"UPSTREAM_BRANCH":              "Upstream branch for update. Default is main.",
	"GOFILE_TOKEN":                 "GoFile account token for /mirror uploads. Without it uploads are made as guest. Get it on https://gofile.io/myProfile",
	"PIXELDRAIN_KEY":               "PixelDrain API key for /mirror uploads. Get it on https://pixeldrain.com/user/api_keys",
	"BUZZHEAVIER_TOKEN":            "BuzzHeavier Account ID (API token) for /mirror uploads.",
	"DEVUPLOADS_KEY":               "DevUploads API key for /mirror uploads. Get it on https://devuploads.com/?op=my_account",
	"STREAMTAPE_API":               "StreamTape API login and key in the format <code>login:key</code> for /mirror uploads.",
	"VIKINGFILE_USER":              "VikingFile user hash for /mirror uploads. Without it uploads are made as guest.",
	"DOWNLOAD_DIR":                 "The path to the local folder where the downloads should be downloaded to.",
	"CMD_SUFFIX":                   "Telegram Bot Command Index number or Custom Text. This will added at the end all commands except Global Commands. Str",
	"AUTHORIZED_CHATS":             "Fill user_id and chat_id of groups/users you want to authorize. Separate them by space.",
	"BLACKLIST_USERS":              "Restrict User from Using the Bot. It will Display a BlackListed Msg. USER_ID separated by space. Str",
	"BOT_PM":                       "Files/links are sent to the BOT PM also. Default is False.",
	"CAP_FONT":                     "Default caption font for leeched files: b, i, u, s, code, spoiler. Empty = regular. A user can choose his own in /us → Leech → Caption Font. Str",
	"LEECH_FILENAME_REMNAME_AUTO":  "Default AutoRename template for leeched file names (users can set their own in /us). Str",
	"LEECH_FILENAME_REMNAME_REGEX": "Regex rules to remove/replace words in leeched file names. Format: <code>word|word2:new</code>. Str",
	"ARIA2_PORT":                   "RPC port of the local aria2c used for direct links. Default is 6800. Int",
	"BASE_URL_PORT":                "Which is the BASE_URL Port. Default is 80. Int",
	"MEGA_EMAIL":                   "E-Mail of a MEGA account. With MEGA_PASSWORD the bot logs in and the download quota is the account's, not the shared server IP's (free accounts help a little, Pro a lot). Accounts with 2FA are not supported. Str",
	"MEGA_PASSWORD":                "Password of the MEGA account (see MEGA_EMAIL). Str",
	"TOKEN_IN_PM":                  "Send the token link to the user in PM instead of the group. Bool",
	"SCREENSHOTS_MODE":             "Enable or Diable generating Screenshots via -ss arg. Default is False. Bool",
	"SHOW_MEDIAINFO":               "Add Button to Show MediaInfo in Leeched file. Bool",
	"METADATA":                     "Default metadata title written into leeched videos (users can set their own in /us). Str",
	"AUTHOR_NAME":                  "Author name for Telegraph pages, Shown in Telegraph Page as by AUTHOR_NAME",
	"AUTHOR_URL":                   "Author URL for Telegraph page, Put Channel URL to Show Join Channel. Str",
	"SHOW_EXTRA_CMDS":              "Add Extra Commands beside Arg Format for -z or -e. <b>COMMANDS: </b> /unzipxxx or /zipxxx or /uzx or /zx",
	"TIMEZONE":                     "Set your Preferred Time Zone for Restart Message (e.g. Asia/Kolkata, Asia/Jerusalem). Get yours at <a href=\"http://www.timezoneconverter.com/cgi-bin/findzone.tzc\">Here</a> Str",
	"FFMPEG_ENCODING":              "Allow re-encoding with FFmpeg (heavy on CPU/RAM). Default is False. Bool",
	"TMDB_ACCESS_TOKEN":            "TMDB API Key or Read Access Token, used for Auto Thumbnail (movie/series poster) in User Settings. Get it from https://www.themoviedb.org/settings/api",
	"DDL_API":                      "API URL of a Telegram direct-download service, used to get a direct link for t.me files before downloading them. Str",
	"QUEUE_ALL":                    "Number of parallel tasks of downloads and uploads. For example if 20 task added and QUEUE_ALL is 8, then the summation of uploading and downloading tasks are 8 and the rest in queue. Int. NOTE: if you want to fill QUEUE_DOWNLOAD or QUEUE_UPLOAD, then QUEUE_ALL value must be greater than or equal to the greatest one and less than or equal to summation of QUEUE_UPLOAD and QUEUE_DOWNLOAD",
	"QUEUE_DOWNLOAD":               "Number of all parallel downloading tasks. Int",
	"QUEUE_UPLOAD":                 "Number of all parallel uploading tasks. Int",
	"STORAGE_THRESHOLD":            "To leave specific storage free and any download will lead to leave free storage less than this value will be cancelled the default unit is GB. Int",
}
